class Solution { public int[] findDiagonalOrder(List<List<Integer>> nums){List<List<Integer>> diagonals=new ArrayList<>();int size=0;for(int row=0;row<nums.size();row++)for(int col=0;col<nums.get(row).size();col++){while(diagonals.size()<=row+col)diagonals.add(new ArrayList<>());diagonals.get(row+col).add(nums.get(row).get(col));size++;}int[] answer=new int[size];int index=0;for(List<Integer> diagonal:diagonals)for(int i=diagonal.size()-1;i>=0;i--)answer[index++]=diagonal.get(i);return answer;} }
